CREATE PROCEDURE core.usp_Load01 @MinId INT=0 AS BEGIN SET NOCOUNT ON; BEGIN TRY; CREATE TABLE #x(Id INT); INSERT #x SELECT Id FROM core.Entity001 WHERE Id>@MinId; MERGE core.Entity002 T USING #x S ON T.Id=S.Id WHEN MATCHED THEN UPDATE SET Code=CONCAT('U',S.Id) WHEN NOT MATCHED THEN INSERT(Code) VALUES(CONCAT('N',S.Id)); END TRY BEGIN CATCH THROW; END CATCH; END;
GO
