-- Dynamic SQL, cursor, recursive CTE and cross-schema examples
CREATE PROCEDURE core.usp_Complex AS BEGIN DECLARE @sql nvarchar(max)=N'SELECT TOP 10 * FROM core.Entity001'; EXEC sp_executesql @sql; DECLARE c CURSOR LOCAL FAST_FORWARD FOR SELECT Id FROM core.Entity002; OPEN c; DECLARE @i int; FETCH NEXT FROM c INTO @i; WHILE @@FETCH_STATUS=0 BEGIN FETCH NEXT FROM c INTO @i; END; CLOSE c; DEALLOCATE c; END;
GO
WITH R AS (SELECT Id,ParentId,0 Lvl FROM core.Entity010 WHERE ParentId IS NULL UNION ALL SELECT E.Id,E.ParentId,R.Lvl+1 FROM core.Entity010 E JOIN R ON E.ParentId=R.Id) SELECT * FROM R OPTION(MAXRECURSION 100);
GO